Con la planta 3 bloqueada, el edificio tiene frecuencias de 2,381 y 4,289 Hz; la FRF puntual en la cubierta tiene mínimos en 2,380 y 4,269 Hz. La primera coincide dentro del $0{,}1\,\%$; la segunda se aparta un $0{,}5\,\%$ porque el amortiguamiento y la cercanía del tercer polo desplazan el mínimo de módulo (con amortiguamiento, el cero exacto sale del eje imaginario).

::: {#tbl-valles .cell tbl-cap='Valles de la receptancia $H_{ij}$ entre 0,5 y 5,5 Hz: frecuencia y profundidad respecto del menor de los dos picos vecinos (dB). Un valle muy profundo indica un cero cerca del eje imaginario.' execution_count=1}
``` {.julia .cell-code}
modulo(i, j) = [abs(Hrec(2π * x)[i, j]) for x in fs]
function valles(i, j)
    v = modulo(i, j)
    m = [k for k in 2:length(v)-1 if v[k] < v[k-1] && v[k] < v[k+1]]
    p = [k for k in 2:length(v)-1 if v[k] > v[k-1] && v[k] > v[k+1]]
    [(fs[k], 20log10(v[k] / min(maximum(v[q] for q in p if fs[q] < fs[k]), maximum(v[q] for q in p if fs[q] > fs[k])))) for k in m]
end
sub = Dict(1 => "₁", 2 => "₂", 3 => "₃")
filas = String[]
for (i, j) in [(1, 1), (2, 2), (3, 3), (1, 2), (2, 3), (1, 3)]
    vs = valles(i, j)
    push!(filas, "| H" * sub[i] * sub[j] * " | " * join(["$(coma(f; d=2)) Hz: $(coma(d; d=1)) dB" for (f, d) in vs], " · ") * " |")
end
Markdown.parse("| Elemento | Valles (frecuencia y profundidad) |\n|:--|:--|\n" * join(filas, "\n"))
```

